{'content': '// Case for 4x Olympus BLS-5 Batteries (56x36x13mm each)
// Linear 4x1 arrangement, batteries standing upright on 13x36mm face
// Batteries face each other on their largest face (56x36mm)

// Battery dimensions
bat_w = 13;    // width (X) - smallest dimension, side-by-side
bat_d = 36;    // depth (Y) - medium dimension
bat_h = 56;    // height (Z) - tallest, standing upright

// Case parameters
wall = 2.0;           // wall thickness
floor_t = 2.0;        // floor thickness
clearance = 0.5;      // clearance around each battery
num_batteries = 4;
divider_t = 1.5;      // divider thickness between batteries

// Slot dimensions (with clearance)
slot_w = bat_w + 2*clearance;  // 14mm
slot_d = bat_d + 2*clearance;  // 37mm
slot_h = bat_h + clearance;    // 56.5mm

// Snap-fit parameters
snap_depth = 1.0;      // how far snap protrudes into slot
snap_height = 4.0;     // height of snap tab
snap_width = 10.0;     // width of snap tab
snap_z = slot_h - 10;  // position from bottom (near top)
snap_chamfer = 1.0;    // entry chamfer

// Finger hole parameters
finger_hole_d = 18;    // diameter of finger hole
finger_hole_depth = 10; // how far into bottom

// Overall case dimensions
case_w = num_batteries * slot_w + (num_batteries - 1) * divider_t + 2 * wall;
case_d = slot_d + 2 * wall;
case_h = slot_h + floor_t;

echo("Case dimensions:", case_w, case_d, case_h);

// Lip/rim at top
lip_h = 3;
lip_inset = 1.0;

module snap_tab() {
    // A snap-fit tab that protrudes into the slot
    // Built as a ramp shape - easy to push battery in, holds it in place
    hull() {
        // Base of tab (flush with wall)
        translate([0, 0, 0])
            cube([0.1, snap_width, snap_height]);
        // Tip of tab (protruding)
        translate([snap_depth, 0, snap_chamfer])
            cube([0.1, snap_width, snap_height - 2*snap_chamfer]);
    }
    // Add entry chamfer at top for easy insertion
    hull() {
        translate([snap_depth, 0, snap_chamfer])
            cube([0.1, snap_width, snap_height - 2*snap_chamfer]);
        translate([0, 0, snap_height])
            cube([0.1, snap_width, 0.1]);
    }
}

module battery_case() {
    difference() {
        union() {
            // Main box
            // Using rounded corners for nicer print
            minkowski() {
                cube([case_w - 4, case_d - 4, case_h/2]);
                translate([2, 2, 0])
                    cylinder(r=2, h=case_h/2, $fn=32);
            }
        }

        // Cut out each battery slot
        for (i = [0:num_batteries-1]) {
            slot_x = wall + i * (slot_w + divider_t);

            // Main slot cavity
            translate([slot_x, wall, floor_t])
                cube([slot_w, slot_d, slot_h + 1]);

            // Finger hole from bottom (through floor)
            translate([slot_x + slot_w/2, wall + slot_d/2, -1])
                cylinder(d=finger_hole_d, h=floor_t + 2, $fn=48);

            // Slight chamfer at top of slot for easy insertion
            translate([slot_x - 0.5, wall - 0.5, case_h - 2])
                linear_extrude(height=2.5, scale=[1.07, 1.03])
                    square([slot_w + 1, slot_d + 1]);
        }
    }

    // Add snap-fit tabs on the divider walls and outer walls
    for (i = [0:num_batteries-1]) {
        slot_x = wall + i * (slot_w + divider_t);
        slot_y_center = wall + slot_d/2;

        // Snap tabs on front and back walls (Y direction) for each slot
        // Front wall tabs
        translate([slot_x + slot_w/2 - snap_width/2, wall, floor_t + snap_z])
            rotate([0, 0, 0])
                snap_tab_y();

        // Back wall tabs  
        translate([slot_x + slot_w/2 + snap_width/2, wall + slot_d, floor_t + snap_z])
            rotate([0, 0, 180])
                snap_tab_y();
    }
}

module snap_tab_y() {
    // Snap tab protruding in Y direction
    hull() {
        cube([snap_width, 0.1, snap_height]);
        translate([0, snap_depth, snap_chamfer])
            cube([snap_width, 0.1, snap_height - 2*snap_chamfer]);
    }
    // Entry ramp
    hull() {
        translate([0, snap_depth, snap_chamfer])
            cube([snap_width, 0.1, snap_height - 2*snap_chamfer]);
        translate([0, 0, snap_height])
            cube([snap_width, 0.1, 0.1]);
    }
}

battery_case();
'}

{'content': '// Case for 4x Olympus BLS-5 Batteries (56x36x13mm each)
// Linear 4x1 arrangement, batteries standing upright on 13x36mm face
// Batteries face each other on their largest face (56x36mm)
// 3D printable in one piece with snap-fit and finger holes

$fn = 48;

// Battery dimensions
bat_w = 13;    // width (X) - smallest dimension
bat_d = 36;    // depth (Y) - medium dimension  
bat_h = 56;    // height (Z) - tallest, standing upright

// Case parameters
wall = 2.5;           // outer wall thickness
floor_t = 2.5;        // floor thickness
clearance = 0.5;      // clearance around each battery per side
num_bat = 4;
divider_t = 1.6;      // divider thickness between batteries

// Slot interior dimensions (with clearance)
slot_w = bat_w + 2*clearance;  // ~14mm
slot_d = bat_d + 2*clearance;  // ~37mm  
slot_h = bat_h + 1.0;          // ~57mm, slight extra height

// Snap-fit parameters
snap_protrusion = 1.2;  // how far snap protrudes into slot
snap_h = 5.0;           // height of snap bump
snap_len = 12.0;        // length of snap tab along wall
snap_z_pos = slot_h - 8; // Z position of snap center (near top)
snap_flex_gap = 0.8;     // gap behind snap for flex (printed as cantilever)
snap_flex_h = 15;         // height of flex zone
snap_wall_t = 1.2;       // thickness of flexible snap wall

// Finger hole parameters
finger_d = 16;          // diameter of finger access hole

// Overall case dimensions
total_slots_w = num_bat * slot_w + (num_bat - 1) * divider_t;
case_w = total_slots_w + 2 * wall;
case_d = slot_d + 2 * wall;
case_h = slot_h + floor_t;

// Corner radius
cr = 3;

echo(str("Case: ", case_w, " x ", case_d, " x ", case_h, " mm"));

// Helper: rounded rectangle
module rounded_rect(w, d, h, r) {
    translate([r, r, 0])
        minkowski() {
            cube([w - 2*r, d - 2*r, h/2]);
            cylinder(r=r, h=h/2);
        }
}

// Snap tab - a flexible cantilever with a bump
// Oriented along Y, protruding in +X
module snap_tab_cantilever(length, protrusion, bump_h) {
    // The bump (rounded)
    translate([0, 0, 0])
    hull() {
        cube([0.01, length, bump_h]);
        translate([protrusion, length*0.1, bump_h*0.15])
            cube([0.01, length*0.8, bump_h*0.7]);
    }
    // Ramp on top for easy insertion
    hull() {
        translate([protrusion, length*0.1, bump_h*0.15 + bump_h*0.7])
            cube([0.01, length*0.8, 0.01]);
        translate([0, 0, bump_h])
            cube([0.01, length, 3]);
    }
}

module case_body() {
    difference() {
        // Outer shell with rounded corners
        rounded_rect(case_w, case_d, case_h, cr);

        // Hollow interior - each slot
        for (i = [0:num_bat-1]) {
            sx = wall + i * (slot_w + divider_t);

            // Main slot
            translate([sx, wall, floor_t])
                cube([slot_w, slot_d, slot_h + 1]);

            // Finger hole through floor
            translate([sx + slot_w/2, wall + slot_d/2, -1])
                cylinder(d=finger_d, h=floor_t + 2);

            // Top chamfer for easy battery insertion (on all 4 edges of slot)
            translate([sx + slot_w/2, wall + slot_d/2, case_h - 3])
                linear_extrude(height=3.5, scale=[(slot_w+4)/slot_w, (slot_d+4)/slot_d])
                    translate([-slot_w/2, -slot_d/2, 0])
                        square([slot_w, slot_d]);
        }
    }
}

// Add snap-fit features
module snap_features() {
    for (i = [0:num_bat-1]) {
        sx = wall + i * (slot_w + divider_t);

        // Two snap tabs per slot on the front wall (Y=wall side)
        // Protruding in +Y direction into the slot
        translate([sx + slot_w/2 - snap_len/2, wall, floor_t + snap_z_pos])
            snap_tab_cantilever(snap_len, snap_protrusion, snap_h);

        // Two snap tabs per slot on the back wall
        // Protruding in -Y direction into the slot
        translate([sx + slot_w/2 + snap_len/2, wall + slot_d, floor_t + snap_z_pos])
            rotate([0, 0, 180])
                snap_tab_cantilever(snap_len, snap_protrusion, snap_h);
    }
}

// Reinforcement ribs on bottom
module bottom_ribs() {
    // Small ribs between finger holes on bottom for strength
    for (i = [0:num_bat-2]) {
        sx = wall + i * (slot_w + divider_t) + slot_w;
        translate([sx, wall + 4, 0])
            cube([divider_t, slot_d - 8, 1.5]);
    }
}

// Label area - slight indentation on front for labeling
module label_areas() {
    for (i = [0:num_bat-1]) {
        sx = wall + i * (slot_w + divider_t);
        // Small number indicator
        translate([sx + slot_w/2, -0.1, floor_t + 5])
            rotate([-90, 0, 0])
                linear_extrude(height=0.8)
                    text(str(i+1), size=6, halign="center", valign="center", font="Liberation Sans:style=Bold");
    }
}

// Main assembly
difference() {
    union() {
        case_body();
        snap_features();
        bottom_ribs();
    }
    label_areas();
}
'}

{'content': '// Case for 4x Olympus BLS-5 Batteries (56x36x13mm each)
// Linear 4x1 arrangement, batteries standing upright on 13x36mm face
// Batteries face each other on their largest face (56x36mm)
// 3D printable in one piece, print upside down (opening facing up)

$fn = 48;

// ==================== PARAMETERS ====================

// Battery dimensions
bat_w = 13;    // width (X) - smallest face
bat_d = 36;    // depth (Y) - medium  
bat_h = 56;    // height (Z) - tallest, standing upright

// Case construction
wall = 2.5;           // outer wall thickness
floor_t = 3.0;        // floor thickness (needs strength around finger holes)
clearance = 0.5;      // clearance per side around battery
num_bat = 4;
divider_t = 1.8;      // divider thickness between slots

// Slot interior dimensions
slot_w = bat_w + 2*clearance;  // 14mm
slot_d = bat_d + 2*clearance;  // 37mm  
slot_h = bat_h + 1.5;          // 57.5mm - battery sits slightly below top

// Snap-fit parameters
snap_protrusion = 1.0;  // how far into slot
snap_bump_h = 4.0;      // height of the bump
snap_len = 10.0;        // width of snap along wall
snap_z = slot_h - 8;    // position near top

// Flexible cantilever for snap (gap behind the snap wall)
flex_gap_w = 0.8;       // gap width for flexibility
flex_gap_h = 20;        // how tall the flex slot is
flex_wall_t = 1.0;      // thin wall that flexes

// Finger hole
finger_d = 16;          // finger hole diameter in floor

// Top chamfer
chamfer_h = 3;
chamfer_extra = 1.5;    // how much wider at top

// Overall dimensions
total_interior_w = num_bat * slot_w + (num_bat - 1) * divider_t;
case_w = total_interior_w + 2 * wall;
case_d = slot_d + 2 * wall;
case_h = slot_h + floor_t;
cr = 3; // corner radius

echo(str("Case dimensions: ", case_w, " x ", case_d, " x ", case_h, " mm"));

// ==================== MODULES ====================

// 2D rounded rectangle
module rrect_2d(w, d, r) {
    offset(r=r) offset(r=-r)
        square([w, d]);
}

// Snap bump profile (2D cross-section in XZ plane)
// Ramp on top for insertion, ledge on bottom for retention
module snap_profile_2d() {
    // Main bump with ramp top
    polygon([
        [0, 0],
        [snap_protrusion, snap_bump_h * 0.2],
        [snap_protrusion, snap_bump_h * 0.65],
        [0, snap_bump_h],
        [0, 0]
    ]);
}

// 3D snap bump, extruded along Y
module snap_bump(length) {
    translate([0, 0, 0])
    rotate([90, 0, 90])
    rotate([0, 90, 0])
    translate([0, 0, 0])
    linear_extrude(height=length)
        snap_profile_2d();
}

// ==================== MAIN CASE ====================

module main_case() {
    difference() {
        // --- Outer shell ---
        linear_extrude(height=case_h)
            rrect_2d(case_w, case_d, cr);

        // --- Battery slots ---
        for (i = [0:num_bat-1]) {
            sx = wall + i * (slot_w + divider_t);

            // Main slot cavity
            translate([sx, wall, floor_t])
                cube([slot_w, slot_d, slot_h + 10]);

            // Finger hole through floor (oval, elongated in Y slightly)
            translate([sx + slot_w/2, wall + slot_d/2, -1])
                scale([1, 1.2, 1])
                    cylinder(d=finger_d, h=floor_t + 2);

            // Top entry chamfer - flare outward for easy insertion
            translate([sx + slot_w/2, wall + slot_d/2, case_h - chamfer_h])
                linear_extrude(height=chamfer_h + 0.1, 
                              scale=[(slot_w + 2*chamfer_extra)/slot_w, 
                                     (slot_d + 2*chamfer_extra)/slot_d])
                    translate([-slot_w/2, -slot_d/2])
                        square([slot_w, slot_d]);

            // --- Flex gaps behind snap tabs (front wall) ---
            // Creates a thin flexible cantilever attached at bottom
            translate([sx + slot_w/2 - snap_len/2 - 1, -0.1, floor_t + snap_z - flex_gap_h + snap_bump_h])
                cube([snap_len + 2, wall - flex_wall_t + 0.1, flex_gap_h]);

            // --- Flex gaps behind snap tabs (back wall) ---
            translate([sx + slot_w/2 - snap_len/2 - 1, wall + slot_d + flex_wall_t, floor_t + snap_z - flex_gap_h + snap_bump_h])
                cube([snap_len + 2, wall - flex_wall_t + 0.1, flex_gap_h]);
        }
    }

    // --- Add snap bumps ---
    for (i = [0:num_bat-1]) {
        sx = wall + i * (slot_w + divider_t);

        // Front wall snap bump (protruding in +Y)
        translate([sx + slot_w/2 - snap_len/2, wall, floor_t + snap_z])
            rotate([0, 0, 0])
                front_snap(snap_len);

        // Back wall snap bump (protruding in -Y)
        translate([sx + slot_w/2 + snap_len/2, wall + slot_d, floor_t + snap_z])
            rotate([0, 0, 180])
                front_snap(snap_len);
    }
}

module front_snap(length) {
    // Snap bump protruding in +Y direction
    // Ramp on top, ledge on bottom
    translate([0, 0, 0])
    rotate([0, 0, 0])
    linear_extrude(height=length) {
        polygon([
            [0, 0],                              // base bottom
            [0, snap_bump_h],                     // base top  
            [snap_protrusion, snap_bump_h * 0.7], // tip upper (ramp)
            [snap_protrusion, snap_bump_h * 0.3], // tip lower
            [0, 0]                                // back to base
        ]);
    }
}

// Wait - the snap needs to protrude into the slot along Y axis.
// Let me redo with proper orientation.

module case_assembly() {
    difference() {
        // --- Outer shell ---
        linear_extrude(height=case_h)
            rrect_2d(case_w, case_d, cr);

        // --- Battery slots ---
        for (i = [0:num_bat-1]) {
            sx = wall + i * (slot_w + divider_t);

            // Main slot cavity
            translate([sx, wall, floor_t])
                cube([slot_w, slot_d, slot_h + 10]);

            // Finger hole through floor
            translate([sx + slot_w/2, wall + slot_d/2, -1])
                cylinder(d=finger_d, h=floor_t + 2);

            // Top entry chamfer
            translate([sx + slot_w/2, wall + slot_d/2, case_h - chamfer_h])
                linear_extrude(height=chamfer_h + 0.1, 
                              scale=[(slot_w + 2*chamfer_extra)/slot_w, 
                                     (slot_d + 2*chamfer_extra)/slot_d])
                    translate([-slot_w/2, -slot_d/2])
                        square([slot_w, slot_d]);
        }

        // --- Flex relief cuts in outer walls behind snaps ---
        for (i = [0:num_bat-1]) {
            sx = wall + i * (slot_w + divider_t);
            center_x = sx + slot_w/2;

            // Front wall flex relief (cut from outside, leave thin flex wall inside)
            translate([center_x - snap_len/2 - 0.5, -0.1, 
                       floor_t + snap_z - 5])
                cube([snap_len + 1, wall - flex_wall_t + 0.1, 
                      flex_gap_h + snap_bump_h]);

            // Back wall flex relief
            translate([center_x - snap_len/2 - 0.5, 
                       wall + slot_d + flex_wall_t, 
                       floor_t + snap_z - 5])
                cube([snap_len + 1, wall - flex_wall_t + 0.1, 
                      flex_gap_h + snap_bump_h]);
        }
    }

    // --- Snap bumps (added as solid geometry) ---
    for (i = [0:num_bat-1]) {
        sx = wall + i * (slot_w + divider_t);
        center_x = sx + slot_w/2;

        // Front wall snap - protrudes in +Y into slot
        translate([center_x - snap_len/2, wall, floor_t + snap_z])
            snap_y_positive(snap_len);

        // Back wall snap - protrudes in -Y into slot  
        translate([center_x - snap_len/2, wall + slot_d, floor_t + snap_z])
            snap_y_negative(snap_len);
    }
}

// Snap tab protruding in +Y direction
module snap_y_positive(len) {
    // Profile in YZ plane, extruded along X
    translate([0, 0, 0])
    rotate([90, 0, 90])
    linear_extrude(height=len) {
        polygon([
            [0, 0],                                // wall surface, bottom
            [snap_protrusion, snap_bump_h * 0.25],  // tip bottom (ledge)
            [snap_protrusion, snap_bump_h * 0.65],  // tip top
            [0, snap_bump_h],                        // wall surface, top (ramp)
        ]);
    }
}

// Snap tab protruding in -Y direction
module snap_y_negative(len) {
    translate([0, 0, 0])
    rotate([90, 0, 90])
    linear_extrude(height=len) {
        polygon([
            [0, 0],                                  // wall surface, bottom
            [-snap_protrusion, snap_bump_h * 0.25],   // tip bottom (ledge)
            [-snap_protrusion, snap_bump_h * 0.65],   // tip top  
            [0, snap_bump_h],                          // wall surface, top (ramp)
        ]);
    }
}

// Number labels engraved on front
module labels() {
    for (i = [0:num_bat-1]) {
        sx = wall + i * (slot_w + divider_t);
        translate([sx + slot_w/2, -0.01, floor_t + 8])
            rotate([90, 0, 180])
                linear_extrude(height=0.8)
                    text(str(i+1), size=7, halign="center", valign="center", 
                         font="Liberation Sans:style=Bold");
    }
}

// Final assembly
difference() {
    case_assembly();
    labels();
}
'}

{'content': '// =============================================================
// Case for 4x Olympus BLS-5 Batteries (56 x 36 x 13 mm each)
// Linear 4×1 arrangement, upright on 13×36 mm face
// Snap-fit retention + finger holes for removal
// Print orientation: opening facing UP, no supports needed
// =============================================================

$fn = 64;

// ---------- Battery ----------
bat_w  = 13;   // X – narrow
bat_d  = 36;   // Y – medium (largest faces touch dividers)
bat_h  = 56;   // Z – tall

// ---------- Tolerances ----------
tol    = 0.5;  // clearance per side

// ---------- Construction ----------
wall   = 2.5;
floor_t = 3.0;
divider = 1.8;
num    = 4;

// ---------- Derived slot dims ----------
sw = bat_w + 2*tol;   // 14
sd = bat_d + 2*tol;   // 37
sh = bat_h + 2.0;     // 58 – battery sits a bit recessed

// ---------- Case dims ----------
interior_w = num*sw + (num-1)*divider;
cw = interior_w + 2*wall;
cd = sd + 2*wall;
ch = sh + floor_t;
cr = 3;

echo(str("Case: ",cw,"×",cd,"×",ch," mm"));

// ---------- Snap-fit ----------
snap_into    = 1.0;   // protrusion into slot
snap_bh      = 4.0;   // bump height (Z)
snap_len     = 10;    // bump length (X)
snap_z       = sh-8;  // Z position inside slot (near top)

// ---------- Finger hole ----------
fhole_d = 16;

// ---------- Chamfer ----------
cham_h  = 3;
cham_ex = 1.5;

// ======================== 2D helpers ========================

module rrect(w,d,r){
    offset(r) offset(-r) square([w,d]);
}

// ======================== Snap profile ========================
// 2D cross-section in Y-Z plane: ramp top, ledge bottom
// Protrudes in +Y, height along Z
module snap_2d(){
    polygon([
        [0,           0],
        [snap_into,   snap_bh*0.25],
        [snap_into,   snap_bh*0.60],
        [0,           snap_bh],
    ]);
}

// ======================== CASE ========================

module the_case(){

  difference(){
    union(){
      // ---- outer shell ----
      linear_extrude(ch) rrect(cw, cd, cr);

      // ---- snap bumps (front & back of each slot) ----
      for(i=[0:num-1]){
        sx = wall + i*(sw+divider);
        cx = sx + sw/2;

        // front snap (+Y protrusion from front inner wall)
        translate([cx - snap_len/2, wall, floor_t + snap_z])
          rotate([90,0,90])
            linear_extrude(snap_len) snap_2d();

        // back snap (-Y protrusion from back inner wall)
        translate([cx + snap_len/2, wall+sd, floor_t + snap_z])
          rotate([90,0,90])
            mirror([0,0,0])
            linear_extrude(snap_len)
              mirror([1,0]) snap_2d();
      }
    }

    // ---- slot cavities ----
    for(i=[0:num-1]){
      sx = wall + i*(sw+divider);
      cx = sx + sw/2;
      cy = wall + sd/2;

      // main cavity
      translate([sx, wall, floor_t])
        cube([sw, sd, sh+10]);

      // finger hole (slightly oval for comfort)
      translate([cx, cy, -1])
        resize([fhole_d, fhole_d*1.1, 0])
          cylinder(d=fhole_d, h=floor_t+2);

      // top chamfer / flare
      translate([cx, cy, ch - cham_h])
        linear_extrude(cham_h+0.1,
          scale=[(sw+2*cham_ex)/sw, (sd+2*cham_ex)/sd])
          translate([-sw/2,-sd/2]) square([sw,sd]);

      // ---- flex relief slots in front wall ----
      // Thin vertical slot on each side of snap, allowing flex
      // Left relief
      translate([cx - snap_len/2 - 0.6, -0.1,
                 floor_t + snap_z - 2])
        cube([0.8, wall+0.2, snap_bh + 4]);
      // Right relief
      translate([cx + snap_len/2 - 0.2, -0.1,
                 floor_t + snap_z - 2])
        cube([0.8, wall+0.2, snap_bh + 4]);

      // ---- flex relief slots in back wall ----
      translate([cx - snap_len/2 - 0.6, wall+sd-0.1,
                 floor_t + snap_z - 2])
        cube([0.8, wall+0.2, snap_bh + 4]);
      translate([cx + snap_len/2 - 0.2, wall+sd-0.1,
                 floor_t + snap_z - 2])
        cube([0.8, wall+0.2, snap_bh + 4]);
    }

    // ---- number labels on front face ----
    for(i=[0:num-1]){
      sx = wall + i*(sw+divider);
      translate([sx + sw/2, 0.8, floor_t + 6])
        rotate([90,0,0])
          linear_extrude(1.0)
            text(str(i+1), size=7, halign="center",
                 valign="center",
                 font="Liberation Sans:style=Bold");
    }

    // ---- "BLS-5" label on front bottom ----
    translate([cw/2, 0.8, floor_t + sh - 8])
      rotate([90,0,0])
        linear_extrude(1.0)
          text("BLS-5", size=5, halign="center",
               valign="center",
               font="Liberation Sans");
  }
}

the_case();
'}

{'content': '// =============================================================
// Case for 4x Olympus BLS-5 Batteries (56 x 36 x 13 mm each)
// Linear 4×1 arrangement, upright on 13×36 mm face
// Snap-fit retention + finger holes for removal
// Print orientation: opening facing UP, no supports needed
// =============================================================

$fn = 64;

// ---------- Battery ----------
bat_w  = 13;   // X – narrow
bat_d  = 36;   // Y – medium (largest faces against dividers)
bat_h  = 56;   // Z – tall

// ---------- Tolerances ----------
tol    = 0.5;  // clearance per side

// ---------- Construction ----------
wall   = 2.5;
floor_t = 3.0;
divider = 1.8;
num    = 4;

// ---------- Derived slot dims ----------
sw = bat_w + 2*tol;   // 14
sd = bat_d + 2*tol;   // 37
sh = bat_h + 2.0;     // 58 – battery sits a bit recessed

// ---------- Case dims ----------
interior_w = num*sw + (num-1)*divider;
cw = interior_w + 2*wall;
cd = sd + 2*wall;
ch = sh + floor_t;
cr = 3;

echo(str("Case: ",cw,"×",cd,"×",ch," mm"));

// ---------- Snap-fit ----------
snap_into    = 1.2;   // protrusion into slot
snap_bh      = 5.0;   // bump height (Z)
snap_len     = 10;    // bump length (X)
snap_z       = sh - 10; // Z position inside slot (near top)

// ---------- Finger hole ----------
fhole_d = 16;

// ---------- Chamfer ----------
cham_h  = 3;
cham_ex = 1.5;

// ======================== CASE ========================

module the_case(){
  difference(){
    // ======== POSITIVE GEOMETRY ========
    union(){
      // ---- Outer shell (solid block with rounded XY corners) ----
      linear_extrude(ch)
        offset(cr) offset(-cr) square([cw, cd]);

      // ---- Snap bumps inside each slot ----
      for(i=[0:num-1]){
        sx = wall + i*(sw + divider);
        cx = sx + sw/2;

        // Front wall snap bump: sits on inner face of front wall
        // protrudes in +Y direction into slot
        translate([cx - snap_len/2, wall, floor_t + snap_z])
          snap_bump_plus_y();

        // Back wall snap bump: sits on inner face of back wall
        // protrudes in -Y direction into slot
        translate([cx + snap_len/2, cd - wall, floor_t + snap_z])
          snap_bump_minus_y();
      }
    }

    // ======== NEGATIVE GEOMETRY (cuts) ========
    for(i=[0:num-1]){
      sx = wall + i*(sw + divider);
      cx = sx + sw/2;
      cy = cd/2;

      // ---- Main slot cavity ----
      // Intentionally leave the snap bumps by stopping
      // the Y cut short where snaps are, but actually
      // the bumps protrude INTO the cavity so they just
      // need to survive the difference. Since they're added
      // in union with the shell, and the cavity cuts inside
      // the shell, the bumps on the wall will remain as they
      // protrude from the wall face.
      translate([sx, wall, floor_t])
        cube([sw, sd, sh + 10]);

      // ---- Finger hole through floor ----
      translate([cx, cy, -1])
        cylinder(d=fhole_d, h=floor_t + 2);

      // ---- Top entry chamfer ----
      translate([cx, cy, ch - cham_h])
        linear_extrude(cham_h + 0.1,
          scale=[(sw + 2*cham_ex)/sw, (sd + 2*cham_ex)/sd])
          translate([-sw/2, -sd/2]) square([sw, sd]);

      // ---- Flex relief: vertical slits flanking each snap ----
      // These allow the wall section with the snap to flex inward
      // Front wall - left slit
      translate([cx - snap_len/2 - 0.8, -0.1, floor_t + snap_z - 3])
        cube([1.0, wall + 0.2, snap_bh + 12]);
      // Front wall - right slit
      translate([cx + snap_len/2 - 0.2, -0.1, floor_t + snap_z - 3])
        cube([1.0, wall + 0.2, snap_bh + 12]);
      // Front wall - horizontal slit at bottom (creates cantilever from below)
      translate([cx - snap_len/2 - 0.8, -0.1, floor_t + snap_z - 3])
        cube([snap_len + 1.6, wall * 0.6, 1.0]);

      // Back wall - left slit
      translate([cx - snap_len/2 - 0.8, cd - wall - 0.1, floor_t + snap_z - 3])
        cube([1.0, wall + 0.2, snap_bh + 12]);
      // Back wall - right slit
      translate([cx + snap_len/2 - 0.2, cd - wall - 0.1, floor_t + snap_z - 3])
        cube([1.0, wall + 0.2, snap_bh + 12]);
      // Back wall - horizontal slit at bottom
      translate([cx - snap_len/2 - 0.8, cd - wall + wall*0.4, floor_t + snap_z - 3])
        cube([snap_len + 1.6, wall * 0.6, 1.0]);
    }

    // ---- Engraved labels on front face ----
    for(i=[0:num-1]){
      sx = wall + i*(sw + divider);
      translate([sx + sw/2, 0.6, floor_t + 8])
        rotate([90, 0, 0])
          linear_extrude(0.8)
            text(str(i+1), size=8, halign="center",
                 valign="center",
                 font="Liberation Sans:style=Bold");
    }

    // ---- "BLS-5" label ----
    translate([cw/2, 0.6, ch - 12])
      rotate([90, 0, 0])
        linear_extrude(0.8)
          text("BLS-5", size=5, halign="center",
               valign="center",
               font="Liberation Sans");
  }
}

// Snap bump protruding in +Y direction
// Origin at wall inner surface, bottom of bump
module snap_bump_plus_y(){
  linear_extrude(snap_len)  // extrude along X (but we need to rotate)
    polygon([]);
  // Actually let's do this properly with translate/rotate
  // Profile in Y-Z plane
  // Y=0 is wall face, positive Y goes into slot, Z goes up

  // Use polyhedron or hull for the bump
  hull(){
    // Base on wall (thin slice)
    translate([0, 0, 0])
      cube([snap_len, 0.01, snap_bh]);
    // Protruding ridge
    translate([0, snap_into, snap_bh*0.2])
      cube([snap_len, 0.01, snap_bh*0.45]);
  }
  // Ramp on top for insertion
  hull(){
    translate([0, snap_into, snap_bh*0.65])
      cube([snap_len, 0.01, 0.01]);
    translate([0, 0, snap_bh])
      cube([snap_len, 0.01, 2.5]);
  }
}

// Snap bump protruding in -Y direction
module snap_bump_minus_y(){
  mirror([0,1,0])
    translate([-(snap_len), 0, 0])
      snap_bump_plus_y();
}

the_case();
'}

{'content': '// =============================================================
// Case for 4× Olympus BLS-5 Batteries (56 × 36 × 13 mm)
// Linear 4×1, upright on 13×36 face, largest faces adjacent
// Snap-fit retention + finger push-out holes
// Print: opening UP, no supports required
// =============================================================

$fn = 64;

// -------------------- Battery --------------------
bat_w  = 13;     // X – narrow side
bat_d  = 36;     // Y – medium side (faces touch dividers)
bat_h  = 56;     // Z – tall, standing upright

// -------------------- Tolerances --------------------
tol = 0.5;       // clearance per side

// -------------------- Construction --------------------
wall     = 2.5;
floor_t  = 3.0;
divider  = 1.8;  // wall between adjacent batteries
num      = 4;

// -------------------- Slot interior --------------------
sw = bat_w + 2*tol;   // 14
sd = bat_d + 2*tol;   // 37
sh = bat_h + 2.0;     // 58  (battery slightly recessed)

// -------------------- Case envelope --------------------
iw = num*sw + (num-1)*divider;
cw = iw + 2*wall;
cd = sd + 2*wall;
ch = sh + floor_t;
cr = 3;

echo(str("Case: ", cw, " × ", cd, " × ", ch, " mm"));

// -------------------- Snap-fit --------------------
snap_into = 1.2;       // protrusion into slot
snap_bh   = 5.0;       // bump height along Z
snap_len  = 10.0;      // bump width along X
snap_z    = sh - 10;   // Z in slot (near top)

// Flex relief
flex_slit_w = 1.0;     // width of vertical slit
flex_slit_h = snap_bh + 14;  // height of flex zone
flex_base_h = 1.0;     // horizontal slit at bottom

// -------------------- Finger hole --------------------
fhole_d = 16;

// -------------------- Top chamfer --------------------
cham_h  = 3.0;
cham_ex = 1.5;

// ==================== MODULES ====================

// Rounded rectangle (XY plane)
module rrect2d(w, d, r) {
    offset(r) offset(-r) square([w, d]);
}

// Snap bump: protrudes in +Y from wall face
// Ramp on top for easy insertion, ledge on bottom for retention
module snap_bump() {
    // Lower portion: wall to tip (ledge)
    hull() {
        cube([snap_len, 0.01, snap_bh]);                          // on wall face
        translate([0, snap_into, snap_bh*0.20])
            cube([snap_len, 0.01, snap_bh*0.45]);                 // tip
    }
    // Upper ramp: tip back to wall
    hull() {
        translate([0, snap_into, snap_bh*0.20 + snap_bh*0.45])
            cube([snap_len, 0.01, 0.01]);                         // top of tip
        translate([0, 0, snap_bh])
            cube([snap_len, 0.01, 2.0]);                          // ramp meets wall
    }
}

// ==================== MAIN CASE ====================

module battery_case() {
    difference() {
        // ======== ADD ========
        union() {
            // Outer shell
            linear_extrude(ch)
                rrect2d(cw, cd, cr);

            // Snap bumps (front & back wall of each slot)
            for (i = [0:num-1]) {
                sx = wall + i*(sw + divider);
                cx = sx + sw/2;

                // Front snap (protrudes +Y into slot from front inner wall)
                translate([cx - snap_len/2, wall, floor_t + snap_z])
                    snap_bump();

                // Back snap (mirrored, protrudes -Y into slot from back inner wall)
                translate([cx + snap_len/2, cd - wall, floor_t + snap_z])
                    mirror([1, 0, 0]) mirror([0, 1, 0])
                        snap_bump();
            }
        }

        // ======== SUBTRACT ========
        for (i = [0:num-1]) {
            sx = wall + i*(sw + divider);
            cx = sx + sw/2;
            cy = cd / 2;

            // Slot cavity
            translate([sx, wall, floor_t])
                cube([sw, sd, sh + 10]);

            // Finger hole (through floor)
            translate([cx, cy, -1])
                cylinder(d=fhole_d, h=floor_t + 2);

            // Top entry chamfer
            translate([cx, cy, ch - cham_h])
                linear_extrude(cham_h + 0.1,
                    scale=[(sw + 2*cham_ex)/sw, (sd + 2*cham_ex)/sd])
                    translate([-sw/2, -sd/2])
                        square([sw, sd]);

            // ---- Flex relief slits (front wall) ----
            fz_bot = floor_t + snap_z - 4;
            // Left slit
            translate([cx - snap_len/2 - flex_slit_w, -0.1, fz_bot])
                cube([flex_slit_w, wall + 0.2, flex_slit_h]);
            // Right slit
            translate([cx + snap_len/2, -0.1, fz_bot])
                cube([flex_slit_w, wall + 0.2, flex_slit_h]);
            // Bottom horizontal slit (creates cantilever anchored at bottom)
            translate([cx - snap_len/2 - flex_slit_w, -0.1, fz_bot])
                cube([snap_len + 2*flex_slit_w, wall*0.55, flex_base_h]);

            // ---- Flex relief slits (back wall) ----
            // Left slit
            translate([cx - snap_len/2 - flex_slit_w, cd - wall - 0.1, fz_bot])
                cube([flex_slit_w, wall + 0.2, flex_slit_h]);
            // Right slit
            translate([cx + snap_len/2, cd - wall - 0.1, fz_bot])
                cube([flex_slit_w, wall + 0.2, flex_slit_h]);
            // Bottom horizontal slit
            translate([cx - snap_len/2 - flex_slit_w, cd - wall*0.55 - 0.1 + 0.1, fz_bot])
                cube([snap_len + 2*flex_slit_w, wall*0.55, flex_base_h]);
        }

        // ---- Engraved slot numbers on front ----
        for (i = [0:num-1]) {
            sx = wall + i*(sw + divider);
            translate([sx + sw/2, 0.6, floor_t + 10])
                rotate([90, 0, 0])
                    linear_extrude(0.8)
                        text(str(i+1), size=8, halign="center",
                             valign="center",
                             font="Liberation Sans:style=Bold");
        }

        // ---- "BLS-5" text on back ----
        translate([cw/2, cd - 0.6, floor_t + 10])
            rotate([90, 0, 180])
                linear_extrude(0.8)
                    text("BLS-5", size=5.5, halign="center",
                         valign="center",
                         font="Liberation Sans");
    }
}

battery_case();
'}
